package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevDept string
var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var empFile *os.File
var empReader *bufio.Scanner
var empRec EmpRec
var wsEofFlagInternal bool

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	fracPic := ""
	fracDigits := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
		fracDigits = len(fracPic)
	}
	// count integer digits (Z and 9)
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}

	neg := val.IsNegative()
	absVal := val.Abs()

	// Get integer and fractional string with exactly fracDigits decimals
	// Use StringFixed to get correctly padded representation (rounding already done)
	var fixed string
	if fracDigits > 0 {
		fixed = absVal.StringFixed(int32(fracDigits))
	} else {
		fixed = absVal.StringFixed(0)
	}
	// split
	intStr := ""
	fracStr := ""
	if fracDigits > 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		// ensure frac length
		if len(fracStr) < fracDigits {
			fracStr = fracStr + strings.Repeat("0", fracDigits-len(fracStr))
		} else if len(fracStr) > fracDigits {
			fracStr = fracStr[:fracDigits]
		}
	} else {
		// no fractional part, fixed may still contain dot if val had scale? StringFixed(0) has no dot
		if idx := strings.Index(fixed, "."); idx >= 0 {
			intStr = fixed[:idx]
		} else {
			intStr = fixed
		}
	}
	if intStr == "" {
		intStr = "0"
	}
	// high-order digit dropping: keep low-order intDigits digits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// pad to intDigits with leading zeros
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	// now build integer picture output
	var outInt []rune
	digitIdx := 0
	stillLeading := true
	for _, ch := range intPic {
		if ch == ',' {
			if stillLeading {
				outInt = append(outInt, ' ')
			} else {
				outInt = append(outInt, ',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := rune(intStr[digitIdx])
			digitIdx++
			if ch == 'Z' && stillLeading && d == '0' {
				// Check if there exists a non-zero digit later in intStr?
				// For COBOL, suppression continues until first non-zero digit.
				// We need to look ahead: if all remaining digits are zero and
				// the last placeholder is a '9', we should keep suppressing Z's.
				// So simply keep space.
				outInt = append(outInt, ' ')
				// stillLeading stays true
			} else {
				outInt = append(outInt, d)
				stillLeading = false
			}
		}
	}
	result := string(outInt)
	if fracDigits > 0 {
		result = result + "." + fracStr
	}
	_ = neg
	return result
}

func formatUneditedInt(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func readEmpLine() (string, bool) {
	if !empReader.Scan() {
		return "", false
	}
	line := empReader.Text()
	// pad to 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	return line, true
}

func parseEmpRec(line string) EmpRec {
	erId := line[0:5]
	erDept := line[5:8]
	hoursStr := line[8:12]
	rateStr := line[12:17]

	hoursDigits := int64(0)
	fmt.Sscanf(hoursStr, "%d", &hoursDigits) // but hoursStr may have leading zeros and spaces? Actually digits only
	// Safer: parse manually
	hoursDigits = 0
	for _, ch := range hoursStr {
		if ch >= '0' && ch <= '9' {
			hoursDigits = hoursDigits*10 + int64(ch-'0')
		} else if ch == ' ' {
			hoursDigits = hoursDigits * 10
		}
	}
	rateDigits := int64(0)
	for _, ch := range rateStr {
		if ch >= '0' && ch <= '9' {
			rateDigits = rateDigits*10 + int64(ch-'0')
		} else if ch == ' ' {
			rateDigits = rateDigits * 10
		}
	}
	// Use decimal.New(n, -scale)
	erHours := decimal.New(hoursDigits, -1)
	erRate := decimal.New(rateDigits, -2)
	return EmpRec{
		ErId:    erId,
		ErDept:  erDept,
		ErHours: erHours,
		ErRate:  erRate,
	}
}

func MAINPARA() {
	// OPEN INPUT EMP-FILE
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If file does not exist, treat as empty
		empFile = nil
		empReader = bufio.NewScanner(strings.NewReader(""))
	} else {
		empReader = bufio.NewScanner(empFile)
	}
	READPARA()
	for !wsEofFlagInternal {
		PROCESSPARA()
	}
	if WsFirstFlag != "Y" { // NOT FIRST-RECORD
		DEPTBREAKPARA()
	}
	if empFile != nil {
		empFile.Close()
	}
	GRANDPARA()
}

func READPARA() {
	line, ok := readEmpLine()
	if !ok {
		wsEofFlagInternal = true
		WsEofFlag = "Y"
		return
	}
	empRec = parseEmpRec(line)
}

func PROCESSPARA() {
	if WsFirstFlag == "Y" {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DEPTBREAKPARA()
			WsPrevDept = empRec.ErDept
		}
	}
	PAYPARA()
	READPARA()
}

func PAYPARA() {
	if empRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = empRec.ErHours.Sub(decimal.NewFromInt(40))
	} else {
		WsRegHours = empRec.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.New(15, -1) // 1.5
	raw := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	WsGross = raw.Round(2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount = WsDeptCount + 1
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount = WsGrandCount + 1

	WsHoursEd = formatEdited(empRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(empRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED
	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPTBREAKPARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	deptCountStr := formatUneditedInt(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, deptCountStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRANDPARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	grandCountStr := formatUneditedInt(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", grandCountStr, WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0

	MAINPARA()
}
